import { QRCodeSVG } from "qrcode.react";
import React from "react";

interface QRCodeModalProps {
  show: boolean;
  onClose: () => void;
  url: string;
  shortCode: string;
}

const QRCodeModal: React.FC<QRCodeModalProps> = ({ show, onClose, url, shortCode }) => {
  if (!show) return null;

  const handleDownload = () => {
    const svg = document.getElementById("qr-code-svg");
    if (!svg) return;
    const serializer = new XMLSerializer();
    const source = serializer.serializeToString(svg);
    const blob = new Blob([source], { type: "image/svg+xml" });
    const urlObj = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = urlObj;
    link.download = `${shortCode}-qr.svg`;
    link.click();
    URL.revokeObjectURL(urlObj);
  };

  return (
    <div
      className="modal fade show d-block"
      tabIndex={-1}
      style={{ backgroundColor: "rgba(15, 23, 42, 0.6)" }}
      onClick={(e) => {
        if (e.target === e.currentTarget) onClose();
      }}
    >
      <div className="modal-dialog modal-dialog-centered modal-sm">
        <div className="modal-content border-0 shadow-lg" style={{ borderRadius: 16 }}>
          <div className="modal-header border-0 pb-0">
            <h5 className="modal-title fw-bold">QR Code</h5>
            <button type="button" className="btn-close" onClick={onClose}></button>
          </div>
          <div className="modal-body text-center py-4">
            <div className="d-inline-block p-3 bg-white border rounded-3 mb-3">
              <QRCodeSVG id="qr-code-svg" value={url} size={180} />
            </div>
            <p className="text-muted small text-break mb-3">{url}</p>
            <button className="btn btn-primary w-100" onClick={handleDownload}>
              <i className="bi bi-download me-2"></i>Download SVG
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default QRCodeModal;
