import { createAsyncThunk, createSlice, PayloadAction } from "@reduxjs/toolkit";
import Path from "../../api.json";
import constant from "../../constant/constant";
import { GetData, PostData } from "../../services/api";
import { ApiErrorResponse, PlanDefinition, PlanId, Transaction } from "../../types";
import { getDataFromLocalStorage } from "../../utility";

interface SubscriptionState {
  plans: PlanDefinition[];
  currentPlan: PlanDefinition | null;
  planRenewsAt: string | null;
  transactions: Transaction[];
  clientToken: string | null;
  plansLoading: boolean;
  clientTokenLoading: boolean;
  checkoutLoading: boolean;
  transactionsLoading: boolean;
  subscribedPlan: any;
  cancelSubscriptionLoading: boolean
}

const initialState: SubscriptionState = {
  plans: [],
  currentPlan: null,
  planRenewsAt: null,
  transactions: [],
  clientToken: null,
  plansLoading: false,
  clientTokenLoading: false,
  checkoutLoading: false,
  subscribedPlan: null,
  transactionsLoading: false,

  cancelSubscriptionLoading: false
};

const extractError = (error: any): string => {
  const data: ApiErrorResponse | undefined = error?.response?.data;
  return data?.message || "Something went wrong. Please try again.";
};

export const fetchPlans = createAsyncThunk("subscription/fetchPlans", async (_, { dispatch, rejectWithValue }) => {
  try {
    const storedToken = getDataFromLocalStorage(constant.AUTHTHOKEN);
    const { data } = await GetData(storedToken, Path.BRAINTREE_PLANS_API);
    return data?.response ?? [];
  } catch (error) {
    return rejectWithValue(extractError(error));
  }
});

export const fetchMySubscription = createAsyncThunk(
  "subscription/fetchMine",
  async (_, { rejectWithValue }) => {
    try {
      const storedToken = getDataFromLocalStorage(constant.AUTHTHOKEN);
      const { data } = await GetData(storedToken, Path.BRAINTREE_MYPLAN_API);
      return data?.response;
    } catch (error) {
      return rejectWithValue(extractError(error));
    }
  }
);

export const fetchMyTransactions = createAsyncThunk(
  "subscription/fetchMyTransactions",
  async (_, { rejectWithValue }) => {
    try {
      const storedToken = getDataFromLocalStorage(constant.AUTHTHOKEN);
      const { data } = await GetData(storedToken, Path.BRAINTREE_TRANSACTIONS_API);
      return data?.response;
    }
    catch (error) {
      return rejectWithValue(extractError(error))
    }
  }
)

export const fetchClientToken = createAsyncThunk(
  "subscription/fetchClientToken",
  async (_, { rejectWithValue }) => {
    try {
      const storedToken = getDataFromLocalStorage(constant.AUTHTHOKEN);
      const { data } = await GetData(storedToken, Path.BRAINTREE_CLIENTTOKEN_API);
      return data?.response as string;
    } catch (error) {
      return rejectWithValue(extractError(error));
    }
  }
);

export const checkout = createAsyncThunk(
  "subscription/checkout",
  async (payload: { planId: PlanId; paymentMethodNonce?: string }, { rejectWithValue }) => {
    try {
      const storedToken = getDataFromLocalStorage(constant.AUTHTHOKEN);
      const { data } = await PostData(storedToken, payload, Path.BRAINTREE_CHECKOUT_API);
      return data?.response;
    } catch (error) {
      return rejectWithValue(extractError(error));
    }
  }
);

export const cancelSubscription = createAsyncThunk(
  "subscription/cancel",
  async (payload: { subscriptionId: string | undefined | null }, { rejectWithValue }) => {
    try {
      const storedToken = getDataFromLocalStorage(constant.AUTHTHOKEN);
      const { data } = await PostData(storedToken, payload, Path.BRAINTREE_MYPLAN_CANCEL_API);
      return data?.response;
    } catch (error) {
      return rejectWithValue(extractError(error));
    }
  }
);

const subscriptionSlice = createSlice({
  name: "subscription",
  initialState,
  reducers: {
    clearClientToken: (state) => {
      state.clientToken = null;
    }
  },
  extraReducers: (builder) => {
    builder
      .addCase(fetchPlans.pending, (state) => {
        state.plansLoading = true;
      })
      .addCase(fetchPlans.fulfilled, (state, action: PayloadAction<PlanDefinition[]>) => {
        state.plansLoading = false;
        state.plans = action.payload;
      })
      .addCase(fetchPlans.rejected, (state) => {
        state.plansLoading = false;
      })
      .addCase(fetchMySubscription.fulfilled, (state, action) => {
        state.subscribedPlan = action.payload;
      })
      .addCase(fetchMyTransactions.pending, (state) => {
        state.transactionsLoading = true;
      })
      .addCase(fetchMyTransactions.fulfilled, (state, action) => {
        state.transactionsLoading = false;
        state.transactions = action.payload;
      })
      .addCase(fetchMyTransactions.rejected, (state) => {
        state.transactionsLoading = false;
      })
      .addCase(fetchClientToken.pending, (state) => {
        state.clientTokenLoading = true;
      })
      .addCase(fetchClientToken.fulfilled, (state, action: PayloadAction<string>) => {
        state.clientTokenLoading = false;
        state.clientToken = action.payload;
      })
      .addCase(fetchClientToken.rejected, (state) => {
        state.clientTokenLoading = false;
      })
      .addCase(checkout.pending, (state) => {
        state.checkoutLoading = true;
      })
      .addCase(checkout.fulfilled, (state, action) => {
        state.checkoutLoading = false;
        state.subscribedPlan = action.payload.mySubscription;
      })
      .addCase(checkout.rejected, (state) => {
        state.checkoutLoading = false;
      })
      .addCase(cancelSubscription.pending, (state) => {
        state.cancelSubscriptionLoading = true;
      })
      .addCase(cancelSubscription.fulfilled, (state) => {
        state.cancelSubscriptionLoading = false;
      })
      .addCase(cancelSubscription.rejected, (state) => {
        state.cancelSubscriptionLoading = false;
      });
  },
});

export const { clearClientToken } = subscriptionSlice.actions;
export default subscriptionSlice.reducer;
